<script setup lang="ts">
/**
 * Label and value pairs describing one entity (`design/components/description-list.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/description-list.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type VNode } from 'vue'

import styles from '@polymorph/recipes/structure/description-list.module.css'

export interface DescriptionListItem {
  term: string
  detail: VNode | string
}

export type DescriptionListOrientation = NonNullable<DescriptionListProps['orientation']>

export interface DescriptionListProps {
  /**
   * Rendered in the order given (Stat's rule: sorting is data logic).
   */
  items: DescriptionListItem[]
  /**
   * `vertical` (default) stacks term over detail and works at any width, as in Timeline, because
   * metadata often sits in a narrow aside. `horizontal` puts a term column beside the details.
   */
  orientation?: 'horizontal' | 'vertical'
}

defineOptions({ name: 'DescriptionList', inheritAttrs: false })

withDefaults(defineProps<DescriptionListProps>(), { orientation: 'vertical' })
</script>

<template>
  <dl
    v-if="items.length > 0"
    :class="styles.root"
    :data-orientation="orientation"
    data-member="description-list"
  >
    <template v-for="(item, index) in items" :key="index">
      <div :class="styles.pair">
        <dt :class="styles.term">
          {{ item.term }}
        </dt>
        <dd :class="styles.detail">
          <template v-if="typeof item.detail === 'string'">{{ item.detail }}</template>
          <template v-else>
            <component :is="item.detail" />
          </template>
        </dd>
      </div>
    </template>
  </dl>
</template>
